import java.util.*;

class DetectSquares {
    private final Map<Long, Integer> counts = new HashMap<>();
    private final List<int[]> points = new ArrayList<>();

    public DetectSquares() {
    }

    public void add(int[] point) {
        counts.merge(key(point[0], point[1]), 1, Integer::sum);
        points.add(new int[] {point[0], point[1]});
    }

    public int count(int[] point) {
        int px = point[0];
        int py = point[1];
        int answer = 0;
        for (int[] opposite : points) {
            int x = opposite[0];
            int y = opposite[1];
            if (Math.abs(px - x) != Math.abs(py - y) || px == x || py == y) {
                continue;
            }
            answer += counts.getOrDefault(key(px, y), 0) * counts.getOrDefault(key(x, py), 0);
        }
        return answer;
    }

    private long key(int x, int y) {
        return ((long) x << 32) | (y & 0xffffffffL);
    }
}

