import java.util.*;

class DetectSquares {
    private final Map<Integer, Map<Integer, Integer>> columns = new HashMap<>();

    public DetectSquares() {
    }

    public void add(int[] point) {
        columns.computeIfAbsent(point[0], key -> new HashMap<>())
                .merge(point[1], 1, Integer::sum);
    }

    public int count(int[] point) {
        int x = point[0];
        int y = point[1];
        Map<Integer, Integer> sameColumn = columns.get(x);
        if (sameColumn == null) {
            return 0;
        }

        int answer = 0;
        for (Map.Entry<Integer, Integer> entry : sameColumn.entrySet()) {
            int otherY = entry.getKey();
            int verticalCount = entry.getValue();
            int side = otherY - y;
            if (side == 0) {
                continue;
            }
            answer += verticalCount * countAt(x + side, y) * countAt(x + side, otherY);
            answer += verticalCount * countAt(x - side, y) * countAt(x - side, otherY);
        }
        return answer;
    }

    private int countAt(int x, int y) {
        Map<Integer, Integer> column = columns.get(x);
        return column == null ? 0 : column.getOrDefault(y, 0);
    }
}

import java.util.*;

class DetectSquares {
    private final Map<Integer, Map<Integer, Integer>> rows = new HashMap<>();

    public DetectSquares() {
    }

    public void add(int[] point) {
        rows.computeIfAbsent(point[1], key -> new HashMap<>())
                .merge(point[0], 1, Integer::sum);
    }

    public int count(int[] point) {
        int x = point[0];
        int y = point[1];
        Map<Integer, Integer> sameRow = rows.get(y);
        if (sameRow == null) {
            return 0;
        }

        int answer = 0;
        for (Map.Entry<Integer, Integer> entry : sameRow.entrySet()) {
            int otherX = entry.getKey();
            int horizontalCount = entry.getValue();
            int side = otherX - x;
            if (side == 0) {
                continue;
            }
            answer += horizontalCount * countAt(x, y + side) * countAt(otherX, y + side);
            answer += horizontalCount * countAt(x, y - side) * countAt(otherX, y - side);
        }
        return answer;
    }

    private int countAt(int x, int y) {
        Map<Integer, Integer> row = rows.get(y);
        return row == null ? 0 : row.getOrDefault(x, 0);
    }
}

import java.util.*;

class DetectSquares {
    private final Map<Long, Integer> counts = new HashMap<>();
    private final Set<Long> uniquePoints = new HashSet<>();

    public DetectSquares() {
    }

    public void add(int[] point) {
        long encoded = key(point[0], point[1]);
        counts.merge(encoded, 1, Integer::sum);
        uniquePoints.add(encoded);
    }

    public int count(int[] point) {
        int px = point[0];
        int py = point[1];
        int answer = 0;
        for (long encoded : uniquePoints) {
            int x = (int) (encoded >> 32);
            int y = (int) (encoded & 0xffffffffL);
            if (Math.abs(px - x) != Math.abs(py - y) || px == x || py == y) {
                continue;
            }
            int diagonalCount = counts.get(encoded);
            answer += diagonalCount
                    * counts.getOrDefault(key(px, y), 0)
                    * counts.getOrDefault(key(x, py), 0);
        }
        return answer;
    }

    private long key(int x, int y) {
        return ((long) x << 32) | (y & 0xffffffffL);
    }
}
